export function validateTraceId(value: TraceId): string[] {
  const errors: string[] = [];
  if (value.length < 16 || value.length > 16) errors.push("value: length must be between 16 and 16");
  return errors;
}

export function validateSpanId(value: SpanId): string[] {
  const errors: string[] = [];
  if (value.length < 8 || value.length > 8) errors.push("value: length must be between 8 and 8");
  return errors;
}

export function validateProperty(value: Property): string[] {
  const errors: string[] = [];
  if (value.key.length < 1 || value.key.length > 64) errors.push("key: length must be between 1 and 64");
  return errors;
}

export function validateMeasurement(value: Measurement): string[] {
  const errors: string[] = [];
  if (value.key.length < 1 || value.key.length > 64) errors.push("key: length must be between 1 and 64");
  if (value.unit !== undefined) {
    if (value.unit.length < 1 || value.unit.length > 32) errors.push("unit: length must be between 1 and 32");
  }
  return errors;
}

export function validateConsent(value: Consent): string[] {
  const errors: string[] = [];
  if (value.policyVersion !== undefined) {
    if (value.policyVersion.length < 1 || value.policyVersion.length > 64) errors.push("policyVersion: length must be between 1 and 64");
  }
  return errors;
}

export function validateEnvelope(value: Envelope): string[] {
  const errors: string[] = [];
  if (value.release !== undefined) {
    if (value.release.length < 1 || value.release.length > 128) errors.push("release: length must be between 1 and 128");
  }
  if (value.serviceName !== undefined) {
    if (value.serviceName.length < 1 || value.serviceName.length > 128) errors.push("serviceName: length must be between 1 and 128");
  }
  if (value.requestId !== undefined) {
    if (value.requestId.length < 1 || value.requestId.length > 128) errors.push("requestId: length must be between 1 and 128");
  }
  if (value.endUserId !== undefined) {
    if (value.endUserId.length < 1 || value.endUserId.length > 256) errors.push("endUserId: length must be between 1 and 256");
  }
  if (value.anonymousId !== undefined) {
    if (value.anonymousId.length < 1 || value.anonymousId.length > 256) errors.push("anonymousId: length must be between 1 and 256");
  }
  if (value.sdkName.length < 1 || value.sdkName.length > 64) errors.push("sdkName: length must be between 1 and 64");
  if (value.sdkVersion.length < 1 || value.sdkVersion.length > 32) errors.push("sdkVersion: length must be between 1 and 32");
  return errors;
}

